const boot=async()=>{SKEY=SLOTK(META.cur);const sl=META.slots[META.cur]||(META.slots[META.cur]={seed:'11'});GS=fresh(await getMap(sl.seed||'11'),!!sl.blank);ED.fb=new Map();ED.big=sl.blank?[]:null;ED.frozen=!!sl.blank;
 const had=load();rebuild();if(!had&&!sl.blank){ED.fb=new Map(W.PLACED.map(p=>[p[0],[p[1],p[2]]]));ED.big=W.BIGP.map(b=>b.slice());ED.frozen=true;}UN.length=0;RE.length=0;drawUI();syncTop();msg('');};
const makeIsland=async(slot,seed,blank)=>{msg('섬을 만드는 중',0);try{localStorage.removeItem(SLOTK(slot));}catch(e){}META.cur=slot;META.slots[slot]={seed:String(seed),blank,t:Date.now(),name:(blank?'빈 섬':'도시 섬')+' '+slot};saveMeta();await new Promise(r=>setTimeout(r,16));await boot();save();fit();$('isl').hidden=true;$('islb').setAttribute('aria-pressed','false');};
const openSlot=async slot=>{if(slot===META.cur)return;thumbNow();META.cur=slot;saveMeta();msg('불러오는 중',0);await new Promise(r=>setTimeout(r,16));await boot();fit();$('isl').hidden=true;$('islb').setAttribute('aria-pressed','false');};
const thumbNow=()=>{if(!W)return;clrH();r.render(W.sc,cam);const c=document.createElement('canvas');c.width=160;c.height=100;const g=c.getContext('2d'),a=cv.width/cv.height,sw=Math.min(cv.width,cv.height*1.6),sh=sw/1.6;g.fillStyle='#3fa2f5';g.fillRect(0,0,160,100);g.drawImage(cv,(cv.width-sw)/2,(cv.height-sh)/2,sw,sh,0,0,160,100);const sl=META.slots[META.cur]||(META.slots[META.cur]={});sl.thumb=c.toDataURL('image/jpeg',.7);saveMeta();};
const miniMap=M=>{const c=document.createElement('canvas'),n=M.N;c.width=c.height=n;const g=c.getContext('2d'),im=g.createImageData(n,n),oc=b64d(M.ocean),te=b64d(M.terr),ki=b64d(M.kind),lv=b64d(M.LVL);for(let i=0;i<n*n;i++){let col=[0,0,0,0];if(!oc[i]){const l=lv[i]||1,s=.82+l*.06;col=te[i]===M.TWA?[94,196,242,255]:ki[i]===M.K.ROAD?[150,156,170,255]:ki[i]>=2&&ki[i]!==M.K.PARK?[232,226,214,255]:[124*s|0,196*s|0,67*s|0,255];}im.data.set(col,i*4);}g.putImageData(im,0,0);return c.toDataURL();};
let newFor=0,newSeed='11',newBlank=false,owr=0;
const drawIsl=async()=>{const p=$('isl'),rows=[];for(let i=1;i<=3;i++){const sl=META.slots[i],has=!!(sl&&(sl.t||i===1)),r_=document.createElement('div');r_.className='slot'+(i===META.cur?' cur':'');const im=document.createElement(sl&&sl.thumb?'img':'span');im.className='th';if(sl&&sl.thumb){im.src=sl.thumb;im.alt='';}
  const tx=document.createElement('div');tx.className='st';const nm=document.createElement('b');nm.textContent=has?(sl.name||'섬 '+i):'빈 슬롯';const dt=document.createElement('span');dt.textContent=i===META.cur?'지금 섬':has&&sl.t?new Date(sl.t).toLocaleDateString('ko-KR',{month:'short',day:'numeric'})+' '+new Date(sl.t).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'}):'';tx.append(nm,dt);
  r_.append(im,tx);if(has&&i!==META.cur)r_.append(mkb('열기',null,()=>openSlot(i)));r_.append(mkb('새 섬',newFor===i,()=>{newFor=newFor===i?0:i;owr=0;drawIsl();}));rows.push(r_);}
 const kids=[...rows];if(newFor){const box=document.createElement('div');box.className='newi';const grid=document.createElement('div');grid.className='row';
  for(const sd of Object.keys(MAPS)){const M=await getMap(sd),b=mkb('',newSeed===sd,()=>{newSeed=sd;drawIsl();},'지형 '+sd);b.className='card';const im=document.createElement('img');im.className='ic';im.alt='';im.src=M.__mini||(M.__mini=miniMap(M));const t=document.createElement('span');t.textContent='지형 '+(Object.keys(MAPS).indexOf(sd)+1);b.append(im,t);grid.append(b);}
  const opt=document.createElement('div');opt.className='er';opt.append(mkb('도시와 함께',!newBlank,()=>{newBlank=false;drawIsl();}),mkb('빈 섬',newBlank,()=>{newBlank=true;drawIsl();}));
  const sl=META.slots[newFor],busyS=!!(sl&&(sl.t||newFor===1)),go=mkb(busyS&&owr<1?'덮어쓰기':'만들기',null,()=>{if(busyS&&owr<1){owr=1;go.textContent='한 번 더 누르면 덮어씀';return;}makeIsland(newFor,newSeed,newBlank);});go.className='go';opt.append(go);box.append(grid,opt);kids.push(box);}
 p.replaceChildren(...kids);};
$('islb').onclick=()=>{const p=$('isl');p.hidden=!p.hidden;$('islb').setAttribute('aria-pressed',p.hidden?'false':'true');if(!p.hidden){$('env').hidden=true;$('envb').setAttribute('aria-pressed','false');thumbNow();newFor=0;drawIsl();}};
